                for (int i = 0; i < argsTrue.length; i++) {
                    Class<?> type = constructor.getParameterTypes()[i];
                    if (type == java.awt.Dimension.class) {
                        argsTrue[i] = new java.awt.Dimension(100, 100);
                        argsFalse[i] = new java.awt.Dimension(100, 100);
                    } else if (type == boolean.class) {
                        argsTrue[i] = true;
                        argsFalse[i] = false;
                    } else if (type == int.class) {
                        argsTrue[i] = java.awt.image.BufferedImage.TYPE_INT_ARGB;
                        argsFalse[i] = java.awt.image.BufferedImage.TYPE_INT_ARGB;
                    } else if (type == float.class) {
                        argsTrue[i] = 1.0f;
                        argsFalse[i] = 1.0f;
                    } else if (type == java.util.List.class) {
                        argsTrue[i] = java.util.Collections.emptyList();
                        argsFalse[i] = java.util.Collections.emptyList();
                    } else {
                        argsTrue[i] = null;
                        argsFalse[i] = null;
                    }
                }

                net.coobird.thumbnailator.ThumbnailParameter paramTrue = (net.coobird.thumbnailator.ThumbnailParameter) constructor.newInstance(argsTrue);
                net.coobird.thumbnailator.ThumbnailParameter paramFalse = (net.coobird.thumbnailator.ThumbnailParameter) constructor.newInstance(argsFalse);

                boolean fitTrue = paramTrue.fitWithinDimenions();
                boolean fitFalse = paramFalse.fitWithinDimenions();

                assert fitTrue : "Expected fitWithinDimenions to be true when initialized with true";
                assert !fitFalse : "Expected fitWithinDimenions to be false when initialized with false";

